// ---- TWK_Core.mqh: expose ATR(10) of the signal TF on the snapshot (it is already computed for the Supertrend)
struct TwkSnapshot { ... double atr; int prevSigAgo; double prevSigClose; ... };   // fill in CTwkEngine::Evaluate from the series

// ---- TWK_MomentumEA.mq5: inputs (all off = current behaviour)
input group "=== ENTRY QUALITY (filter lab) ==="
input int    MinOppositeSignalBars  = 0;     // skip if the previous opposite signal is younger than this (lab: 10 on M3)
input double MinSignalDistanceATR   = 0.0;   // skip if |close - previous signal close| < this x ATR (lab: 2.0)
input double StopATRFloor           = 0.0;   // SL distance at least this x ATR (lab: 1.0)
input double StopATRCap             = 0.0;   // skip if the SL distance exceeds this x ATR (lab: 4.0)
input group "=== COST GATE ==="
input double MaxCostToReward        = 0.0;   // skip if spread / (RewardRisk x stop) > this (lab: 0.10)
input double MaxCostToStop          = 0.0;   // skip if spread / stop > this (lab: 0.20)
input double SpreadSpikeMultiple    = 2.0;   // existing auto spread limit, keep
input group "=== RISK ==="
input double MaxStopRiskPercent     = 2.0;   // skip if the minimum lot risks more than this
input double MaxDailyLossPercent    = 3.0;   // no new entries after this daily loss
input int    MaxConsecutiveLosses   = 5;     // no new entries for the rest of the day after this streak
// switchable, off by default, kept for re-testing: CooldownMinutesAfterLoss, RequireHTFAlignment, SessionStartHour/EndHour,
// TrailActivationR, LockAtR/LockKeepR, TimeExitMinutes/TimeExitBelowR, OppositeConfirmBars

// ---- ValidateConditions(): after the ADX check, before the stop logic
if(MinOppositeSignalBars > 0 && s.oppAgo >= 0 && s.oppAgo < MinOppositeSignalBars)
   { Reject(StringFormat("RAPID_FLIP: opposite signal %d bars ago", s.oppAgo)); return false; }
if(MinSignalDistanceATR > 0 && MathAbs(s.close - s.prevSigClose) < MinSignalDistanceATR * s.atr)
   { Reject("CHOP: too close to the previous signal"); return false; }

// ---- ValidateConditions(): stop distance (replaces the pivot-only choice when StopATRFloor > 0)
double dist = s.slFromPivot ? MathAbs(s.close - s.sl) : MathAbs(s.close - s.purple);
if(StopATRFloor > 0) dist = MathMax(dist, StopATRFloor * s.atr);
if(StopATRCap  > 0 && dist > StopATRCap * s.atr) { Reject("STOP_TOO_WIDE"); return false; }
sl = isBuy ? s.close - dist : s.close + dist;  tp = isBuy ? s.close + RewardRisk * dist : s.close - RewardRisk * dist;

// ---- CheckSpread(): cost gate next to the existing spread limit
const double spreadPx = SymbolInfoDouble(_Symbol, SYMBOL_ASK) - SymbolInfoDouble(_Symbol, SYMBOL_BID);
if(MaxCostToReward > 0 && spreadPx / (RewardRisk * dist) > MaxCostToReward) { why = "SPREAD_TOO_HIGH vs reward"; return false; }
if(MaxCostToStop   > 0 && spreadPx / dist > MaxCostToStop)                 { why = "SPREAD_TOO_HIGH vs stop";   return false; }

// ---- CalculateLot(): risk mode becomes the default, with the skip rule
lots = AccountInfoDouble(ACCOUNT_EQUITY) * RiskPercent / 100.0 / MathAbs(lossPerLot);       // lossPerLot from OrderCalcProfit(1.0 lot, entry, sl)
lots = NormalizeLot(lots);
const double minLotLoss = MathAbs(lossPerLot) * SymbolInfoDouble(_Symbol, SYMBOL_VOLUME_MIN);
if(lots <= 0 || minLotLoss > AccountInfoDouble(ACCOUNT_EQUITY) * MaxStopRiskPercent / 100.0) { why = "RISK: min lot exceeds the cap"; return 0; }

// ---- ProcessSignal(): daily loss and streak pause (track g_dayStartEquity, g_dayPnL, g_consecLosses in OnTradeTransaction)
if(g_dayPnL <= -g_dayStartEquity * MaxDailyLossPercent / 100.0) { Reject("RISK: daily loss limit"); return; }
if(g_consecLosses >= MaxConsecutiveLosses && g_pausedDay == TimeCurrent() / 86400) { Reject("RISK: losing streak, paused for today"); return; }
